CREATE FUNCTION api_read.slugify(value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT trim(BOTH '-' FROM regexp_replace(
        lower(translate(
            replace(replace(replace(replace(value, 'œ', 'oe'), 'Œ', 'oe'), 'æ', 'ae'), 'Æ', 'ae'),
            'ÀÂÄÁÃÅàâäáãåÇçÉÈÊËéèêëÍÌÎÏíìîïÑñÓÒÔÖÕóòôöõÚÙÛÜúùûüÝŸýÿ',
            'AAAAAAaaaaaaCcEEEEeeeeIIIIiiiiNnOOOOOoooooUUUUuuuuYYyy'
        )),
        '[^a-z0-9]+', '-', 'g'
    ))
$$;

CREATE VIEW api_read.courses AS
 SELECT c.id,
    c.slug,
    c.titre AS title,
    c.description,
    c.theme,
    split_part((c.theme)::text, ' – '::text, 1) AS subject_name,
    api_read.slugify(split_part((c.theme)::text, ' – '::text, 1)) AS subject_slug,
    NULLIF(split_part((c.theme)::text, ' – '::text, 2), ''::text) AS topic_name,
    NULLIF(api_read.slugify(split_part((c.theme)::text, ' – '::text, 2)), ''::text) AS topic_slug,
    c.difficulte AS difficulty,
    ARRAY( SELECT DISTINCT
                CASE
                    WHEN (t.value = ANY (ARRAY['collège'::text, 'college'::text])) THEN 'college'::text
                    WHEN (t.value = ANY (ARRAY['lycée'::text, 'lycee'::text])) THEN 'lycee'::text
                    WHEN (t.value = ANY (ARRAY['supérieur'::text, 'superieur'::text])) THEN 'superieur'::text
                    ELSE NULL::text
                END AS "case"
           FROM jsonb_array_elements_text(COALESCE((c.tags)::jsonb, '[]'::jsonb)) t(value)
          WHERE (t.value = ANY (ARRAY['collège'::text, 'college'::text, 'lycée'::text, 'lycee'::text, 'supérieur'::text, 'superieur'::text]))
          ORDER BY
                CASE
                    WHEN (t.value = ANY (ARRAY['collège'::text, 'college'::text])) THEN 'college'::text
                    WHEN (t.value = ANY (ARRAY['lycée'::text, 'lycee'::text])) THEN 'lycee'::text
                    WHEN (t.value = ANY (ARRAY['supérieur'::text, 'superieur'::text])) THEN 'superieur'::text
                    ELSE NULL::text
                END) AS levels,
    c.duree_estimee AS duration_minutes,
    COALESCE((c.tags)::jsonb, '[]'::jsonb) AS tags,
    u.pseudo AS author_pseudo,
    (( SELECT count(*) AS count
           FROM site.chapters ch
          WHERE (ch.course_id = c.id)))::integer AS chapter_count,
    (( SELECT count(*) AS count
           FROM (site.lessons l
             JOIN site.chapters ch ON ((ch.id = l.chapter_id)))
          WHERE (ch.course_id = c.id)))::integer AS lesson_count,
    (( SELECT count(*) AS count
           FROM (site.exercises e
             JOIN site.chapters ch ON ((ch.id = e.chapter_id)))
          WHERE (ch.course_id = c.id)))::integer AS exercise_count,
    (c.published_at AT TIME ZONE 'UTC'::text) AS published_at,
    (c.updated_at AT TIME ZONE 'UTC'::text) AS updated_at
   FROM (site.courses c
     LEFT JOIN site.users u ON ((u.id = c.auteur_id)))
  WHERE (((c.statut)::text = 'publie'::text) AND (c.published_at IS NOT NULL) AND (c.published_at <= (now() AT TIME ZONE 'UTC'::text)));

CREATE VIEW api_read.chapters AS
 SELECT ch.id,
    ch.course_id,
    ch.ordre AS "position",
    ch.titre AS title
   FROM (site.chapters ch
     JOIN api_read.courses c ON ((c.id = ch.course_id)));

CREATE VIEW api_read.chapter_translations AS
 SELECT t.traduisible_id AS chapter_id,
    t.langue AS lang,
    NULLIF(((t.champs)::jsonb ->> 'titre'::text), ''::text) AS title
   FROM (site.contenu_translations t
     JOIN api_read.chapters ch ON ((ch.id = t.traduisible_id)))
  WHERE ((t.traduisible_type)::text = 'chapter'::text);

CREATE VIEW api_read.course_translations AS
 SELECT t.traduisible_id AS course_id,
    t.langue AS lang,
    NULLIF(((t.champs)::jsonb ->> 'titre'::text), ''::text) AS title,
    NULLIF(((t.champs)::jsonb ->> 'description'::text), ''::text) AS description
   FROM (site.contenu_translations t
     JOIN api_read.courses c ON ((c.id = t.traduisible_id)))
  WHERE ((t.traduisible_type)::text = 'course'::text);

CREATE VIEW api_read.exams AS
 SELECT x.id,
    x.slug,
    x.titre AS title,
    x.type,
    x.concours AS competition,
    x.matiere AS subject,
    x.pays AS country,
    x.niveau AS level,
    COALESCE((x.filieres)::jsonb, '[]'::jsonb) AS tracks,
    x.session,
    x.duree_minutes AS duration_minutes,
    x.points_total AS total_points,
    x.description,
    (x.fichier_pdf IS NOT NULL) AS has_pdf,
        CASE
            WHEN ((u.hote = 'www.concours-centrale-supelec.fr'::text) AND starts_with(u.chemin, '/sites/default/files/documents/'::text) AND (lower(u.chemin) ~~ '%.pdf'::text) AND (POSITION(('..'::text) IN (u.chemin)) = 0)) THEN o.url
            ELSE NULL::text
        END AS official_url,
    x.url_source AS source_url,
    (( SELECT count(*) AS count
           FROM site.exam_parties p
          WHERE (p.exam_id = x.id)))::integer AS part_count,
    (x.published_at AT TIME ZONE 'UTC'::text) AS published_at,
    (x.updated_at AT TIME ZONE 'UTC'::text) AS updated_at
   FROM ((site.exams x
     CROSS JOIN LATERAL ( SELECT btrim((x.url_officielle)::text, ' 	
'::text) AS url) o)
     CROSS JOIN LATERAL ( SELECT lower("substring"(o.url, '^https://([^/?#]*)'::text)) AS hote,
            "substring"(o.url, '^https://[^/?#]*([^?#]*)'::text) AS chemin) u)
  WHERE (((x.statut)::text = 'publie'::text) AND (x.published_at IS NOT NULL) AND (x.published_at <= (now() AT TIME ZONE 'UTC'::text)));

CREATE VIEW api_read.exam_parts AS
 SELECT p.id,
    p.exam_id,
    p.ordre AS "position",
    p.titre AS title,
    p.enonce_md AS statement_md,
    p.points
   FROM (site.exam_parties p
     JOIN api_read.exams x ON ((x.id = p.exam_id)));

CREATE VIEW api_read.exam_part_translations AS
 SELECT t.traduisible_id AS exam_part_id,
    t.langue AS lang,
    NULLIF(((t.champs)::jsonb ->> 'titre'::text), ''::text) AS title,
    NULLIF(((t.champs)::jsonb ->> 'enonce_md'::text), ''::text) AS statement_md
   FROM (site.contenu_translations t
     JOIN api_read.exam_parts p ON ((p.id = t.traduisible_id)))
  WHERE ((t.traduisible_type)::text = 'exam_partie'::text);

CREATE VIEW api_read.exercises AS
 SELECT e.id,
    e.chapter_id,
    ch.course_id,
    e.type,
    e.titre AS title,
    e.question_md,
    e.ordre AS "position",
    ch."position" AS chapter_position,
        CASE
            WHEN ((e.type)::text = 'qcm'::text) THEN ( SELECT COALESCE(jsonb_agg(jsonb_build_object('id', (x.o ->> 'id'::text), 'text', (x.o ->> 'texte'::text)) ORDER BY x.n), '[]'::jsonb) AS "coalesce"
               FROM jsonb_array_elements(
                    CASE
                        WHEN (jsonb_typeof(((e.donnees)::jsonb -> 'options'::text)) = 'array'::text) THEN ((e.donnees)::jsonb -> 'options'::text)
                        ELSE '[]'::jsonb
                    END) WITH ORDINALITY x(o, n))
            ELSE NULL::jsonb
        END AS options,
        CASE
            WHEN ((e.type)::text = 'qcm'::text) THEN
            CASE
                WHEN (jsonb_typeof(((e.donnees)::jsonb -> 'correctes'::text)) = 'array'::text) THEN (jsonb_array_length(((e.donnees)::jsonb -> 'correctes'::text)) > 1)
                ELSE false
            END
            ELSE NULL::boolean
        END AS multiple,
    (e.updated_at AT TIME ZONE 'UTC'::text) AS updated_at
   FROM (site.exercises e
     JOIN api_read.chapters ch ON ((ch.id = e.chapter_id)));

CREATE VIEW api_read.exercise_translations AS
 SELECT t.traduisible_id AS exercise_id,
    t.langue AS lang,
    NULLIF(((t.champs)::jsonb ->> 'titre'::text), ''::text) AS title,
    NULLIF(((t.champs)::jsonb ->> 'question_md'::text), ''::text) AS question_md,
        CASE
            WHEN ((e.options IS NOT NULL) AND (jsonb_typeof(((t.champs)::jsonb -> 'options'::text)) = 'object'::text)) THEN ( SELECT COALESCE(jsonb_agg(jsonb_build_object('id', (x.o ->> 'id'::text), 'text', COALESCE(NULLIF((((t.champs)::jsonb -> 'options'::text) ->> (x.o ->> 'id'::text)), ''::text), (x.o ->> 'text'::text))) ORDER BY x.n), '[]'::jsonb) AS "coalesce"
               FROM jsonb_array_elements(e.options) WITH ORDINALITY x(o, n))
            ELSE NULL::jsonb
        END AS options
   FROM (site.contenu_translations t
     JOIN api_read.exercises e ON ((e.id = t.traduisible_id)))
  WHERE ((t.traduisible_type)::text = 'exercise'::text);

CREATE VIEW api_read.lessons AS
 SELECT l.id,
    l.chapter_id,
    ch.course_id,
    l.slug,
    l.ordre AS "position",
    ch."position" AS chapter_position,
    l.titre AS title,
    l.contenu_md AS content_md,
    (l.updated_at AT TIME ZONE 'UTC'::text) AS updated_at
   FROM (site.lessons l
     JOIN api_read.chapters ch ON ((ch.id = l.chapter_id)));

CREATE VIEW api_read.lesson_translations AS
 SELECT t.traduisible_id AS lesson_id,
    t.langue AS lang,
    NULLIF(((t.champs)::jsonb ->> 'titre'::text), ''::text) AS title,
    NULLIF(((t.champs)::jsonb ->> 'contenu_md'::text), ''::text) AS content_md
   FROM (site.contenu_translations t
     JOIN api_read.lessons l ON ((l.id = t.traduisible_id)))
  WHERE ((t.traduisible_type)::text = 'lesson'::text);

CREATE VIEW api_read.licenses AS
 SELECT column1 AS key,
    column2 AS name,
    column3 AS url
   FROM (VALUES ('cc-by-4.0'::text,'CC BY 4.0'::text,'https://creativecommons.org/licenses/by/4.0/'::text), ('cc-by-sa-4.0'::text,'CC BY-SA 4.0'::text,'https://creativecommons.org/licenses/by-sa/4.0/'::text), ('cc-by-nc-4.0'::text,'CC BY-NC 4.0'::text,'https://creativecommons.org/licenses/by-nc/4.0/'::text), ('cc-by-nc-sa-4.0'::text,'CC BY-NC-SA 4.0'::text,'https://creativecommons.org/licenses/by-nc-sa/4.0/'::text), ('cc-by-nd-4.0'::text,'CC BY-ND 4.0'::text,'https://creativecommons.org/licenses/by-nd/4.0/'::text), ('cc0-1.0'::text,'CC0 1.0 (domaine public)'::text,'https://creativecommons.org/publicdomain/zero/1.0/'::text), ('domaine-public'::text,'Domaine public'::text,NULL::text), ('tous-droits-reserves'::text,'Tous droits réservés'::text,NULL::text), ('autre'::text,'Autre (à préciser)'::text,NULL::text)) "*VALUES*";

CREATE VIEW api_read.member_brains AS
 SELECT id AS user_id,
    (COALESCE(( SELECT sum(m.montant) AS sum
           FROM site.cerveaux_mouvements m
          WHERE (m.user_id = u.id)), (0)::bigint))::integer AS balance,
    cerveaux_publics AS public
   FROM site.users u;

CREATE VIEW api_read.member_roles AS
 SELECT ru.user_id,
    r.slug,
    r.nom AS name,
    r.categorie AS category,
    r.couleur AS color,
    r.niveau AS permission_level,
    r.ordre AS display_order
   FROM (site.role_user ru
     JOIN site.roles r ON ((r.id = ru.role_id)));

CREATE VIEW api_read.member_xp AS
 WITH counts AS (
         SELECT u.id AS user_id,
            ( SELECT count(*) AS count
                   FROM site.lesson_progress lp
                  WHERE ((lp.user_id = u.id) AND (lp.completed_at IS NOT NULL))) AS lessons,
            ( SELECT count(DISTINCT ea.exercise_id) AS count
                   FROM site.exercise_attempts ea
                  WHERE ((ea.user_id = u.id) AND (ea.correct = true))) AS exercises,
            ( SELECT count(*) AS count
                   FROM site.enrollments en
                  WHERE ((en.user_id = u.id) AND (en.completed_at IS NOT NULL))) AS courses,
            ( SELECT count(*) AS count
                   FROM site.questions q
                  WHERE (q.user_id = u.id)) AS questions,
            ( SELECT count(*) AS count
                   FROM site.answers a
                  WHERE (a.user_id = u.id)) AS answers,
            ( SELECT count(*) AS count
                   FROM (site.answers a
                     JOIN site.questions q ON ((q.accepted_answer_id = a.id)))
                  WHERE (a.user_id = u.id)) AS accepted_answers,
            ( SELECT COALESCE(sum(LEAST((30)::bigint, ((j.parties * 3) + (j.victoires * 5)))), (0)::numeric) AS "coalesce"
                   FROM ( SELECT count(*) AS parties,
                            count(*) FILTER (WHERE ((gr.outcome)::text = 'win'::text)) AS victoires
                           FROM site.game_results gr
                          WHERE (gr.user_id = u.id)
                          GROUP BY ((gr.ended_at)::date)) j) AS game_xp
           FROM site.users u
        ), totals AS (
         SELECT counts.user_id,
            (((((((((counts.lessons * 10) + (counts.exercises * 8)) + (counts.courses * 40)) + (counts.questions * 4)) + (counts.answers * 4)) + (counts.accepted_answers * 12)))::numeric + counts.game_xp))::integer AS total
           FROM counts
        ), levels AS (
         SELECT totals.user_id,
            totals.total,
            (floor((((1)::numeric + sqrt(((1)::numeric + ((totals.total)::numeric * 0.08)))) / (2)::numeric)))::integer AS n
           FROM totals
        )
 SELECT user_id,
    total,
        CASE
            WHEN (((50 * n) * (n + 1)) <= total) THEN (n + 1)
            WHEN (((50 * (n - 1)) * n) > total) THEN (n - 1)
            ELSE n
        END AS level
   FROM levels;

CREATE VIEW api_read.members AS
 SELECT id,
    pseudo,
    avatar AS avatar_path,
    bio,
    (created_at AT TIME ZONE 'UTC'::text) AS member_since
   FROM site.users u;

CREATE VIEW api_read.resources AS
 SELECT id,
    slug,
    titre AS title,
    description,
    categorie AS category,
    langue AS doc_lang,
        CASE
            WHEN ((fichier IS NULL) AND (lien IS NOT NULL)) THEN 'link'::text
            ELSE 'host'::text
        END AS mode,
    auteur_nom AS attribution,
    licence AS license_key,
    licence_personnalisee AS license_custom,
    lien AS source_url,
        CASE
            WHEN (fichier IS NOT NULL) THEN taille
            ELSE NULL::bigint
        END AS size_bytes,
    (created_at AT TIME ZONE 'UTC'::text) AS created_at,
    (updated_at AT TIME ZONE 'UTC'::text) AS updated_at
   FROM site.ressources r
  WHERE (((statut)::text = 'publie'::text) AND ((fichier IS NOT NULL) OR (lien IS NOT NULL)));

CREATE VIEW api_read.resource_translations AS
 SELECT t.traduisible_id AS resource_id,
    t.langue AS lang,
    NULLIF(((t.champs)::jsonb ->> 'titre'::text), ''::text) AS title,
    NULLIF(((t.champs)::jsonb ->> 'description'::text), ''::text) AS description,
    NULLIF(((t.champs)::jsonb ->> 'categorie'::text), ''::text) AS category
   FROM (site.contenu_translations t
     JOIN api_read.resources r ON ((r.id = t.traduisible_id)))
  WHERE ((t.traduisible_type)::text = 'ressource'::text);

CREATE VIEW api_read.subject_names AS
 SELECT column1 AS subject_slug,
    column2 AS lang,
    column3 AS name
   FROM (VALUES ('mathematiques'::text,'en'::text,'Mathematics'::text), ('physique'::text,'en'::text,'Physics'::text), ('chimie'::text,'en'::text,'Chemistry'::text), ('biologie'::text,'en'::text,'Biology'::text), ('informatique'::text,'en'::text,'Computer science'::text), ('cryptographie'::text,'en'::text,'Cryptography'::text), ('mathematiques'::text,'ru'::text,'Математика'::text), ('physique'::text,'ru'::text,'Физика'::text), ('chimie'::text,'ru'::text,'Химия'::text), ('biologie'::text,'ru'::text,'Биология'::text), ('informatique'::text,'ru'::text,'Информатика'::text), ('cryptographie'::text,'ru'::text,'Криптография'::text)) "*VALUES*";


